const roles = ['User', 'Branch manager', 'Department head', 'IT', 'CITO', 'COO', 'HR', 'Super Admin'];
const pagePaths={'Overview':'/','My requests':'/requests','My access':'/my-access','Create a request':'/create-request','Approvals':'/approvals','Reports':'/reports','User directory':'/users','Audit trail':'/audit-trail','Workflow studio':'/admin/workflows','Admin settings':'/admin/settings','Joiners & transfers':'/joiners'};
const routeFromPath=pathname=>{const path=pathname.replace(/\/+$/,'')||'/';const requestMatch=path.match(/^\/requests\/(.+)$/);if(requestMatch)return {page:'My requests',requestId:decodeURIComponent(requestMatch[1])};const page=Object.entries(pagePaths).find(([,route])=>route===path)?.[0]||'Overview';return {page,requestId:null};};
const systems = ['ICBS', 'ITMBD', 'T4S', 'Cheque Clearing', 'BEFTN', 'HRIS', 'Eximbills', 'Swift_Jump', 'Swift ID', 'Swift Demerage ID', 'AD ID', 'Amlock ID', 'Internet Access', 'Quantum', 'ITMBD Test', 'ICBS Test', 'RVI Web Portal Access', 'Query', 'LOS', 'WBO', 'CITRIX_R', 'E-Journal', 'FX Portal', 'NID Verification', 'E2Gen', 'MCAS', 'JIRA ID', 'Remmit Plus', 'Email', 'IDrive', 'N Drive'];
const flowByRole = { User:['Requester','Branch manager','IT','CITO','COO','IT fulfilment','Email'], 'Branch manager':['Requester','Branch manager','IT','CITO','COO','IT fulfilment','Email'], 'Department head':['Requester','Department head','IT','CITO','COO','IT fulfilment','Email'], IT:['Requester','Branch manager','IT','CITO','COO','IT fulfilment','Email'], CITO:['Requester','Branch manager','IT','CITO','COO','IT fulfilment','Email'], COO:['Requester','Branch manager','IT','CITO','COO','IT fulfilment','Email'], HR:['Requester','HR','Branch manager','IT','CITO','COO','IT fulfilment','Email'], 'Super Admin':['Requester','Branch manager','IT','CITO','COO','IT fulfilment','Email'] };
const navFor = role => {
  const base = ['Overview','My requests','Create a request'];
  base.splice(2, 0, 'My access');
  if (approvalRoles.includes(role)) base.push('Approvals');
  if (['IT','CITO','Super Admin'].includes(role)) base.push('Reports');
  if (['IT','CITO','Super Admin'].includes(role)) base.push('User directory','Audit trail');
  if (role === 'Super Admin') base.push('Workflow studio','Admin settings');
  if (role === 'HR') base.push('Joiners & transfers');
  return base;
};
const loadMockUsers=()=>{try{const saved=JSON.parse(localStorage.getItem('uidmsMockUsers')||'null');if(!Array.isArray(saved))return initialUsers;return saved.map(user=>{const seeded=initialUsers.find(item=>item.employeeId===user.employeeId);return {...seeded,...user,department:user.department==='IT Division'?'IT Department':user.department,access:user.access||seeded?.access||{}};});}catch{return initialUsers;}};

function Metric({label,value,note,icon,tone='blue',onClick}) { const content=<><div className="metric-top"><span>{label}</span><i className={`metric-icon mi-${tone}`}><Icon name={icon} size={18}/></i></div><div className="metric-value">{value}</div><small>{note}</small></>;return onClick?<button type="button" className="metric-card metric-card-action" onClick={onClick} aria-label={`${label}: ${value}. ${note}`}>{content}</button>:<article className="metric-card">{content}</article>; }
function Field({label,children}) { return <label className="field-label">{label}{children}</label>; }
function OperationsFinder({users,requests,onViewAccess,onOpenRequest}) {
 const [mode,setMode]=useState('access');const [query,setQuery]=useState('');
 const term=query.trim().toLowerCase();
 const matchedUsers=term?users.filter(user=>`${user.name} ${user.employeeId} ${user.systemId}`.toLowerCase().includes(term)).slice(0,6):[];
 const matchedRequests=term?requests.filter(request=>`${request.id} ${request.name} ${request.requesterId||request.employeeId||''} ${request.system} ${request.action} ${request.role} ${request.branch}`.toLowerCase().includes(term)).slice(0,6):[];
 const matches=mode==='access'?matchedUsers:matchedRequests;
 return <div className="operations-finder"><div className="operations-finder-controls"><select aria-label="Search category" value={mode} onChange={event=>setMode(event.target.value)}><option value="access">Current access</option><option value="requests">New request</option></select><label><Icon name="search" size={16}/><input value={query} onChange={event=>setQuery(event.target.value)} placeholder={mode==='access'?'Search user name or ID':'Search ticket, user or system'}/></label></div>{term&&<div className="operations-finder-results">{matches.length?mode==='access'?matchedUsers.map(user=><article key={user.employeeId}><span><strong>{user.name}</strong><small>{user.employeeId} / {user.role} / {user.branch}</small></span><button type="button" onClick={()=>{onViewAccess(user);setQuery('');}}>View</button></article>):matchedRequests.map(request=><button type="button" className="operations-finder-request" key={request.id} onClick={()=>{onOpenRequest(request);setQuery('');}}><span><strong>{request.id} / {request.action}</strong><small>{request.name} / {request.system} / {request.state}</small></span><Icon name="chevron" size={16}/></button>):<p>No {mode==='access'?'users':'requests'} found.</p>}</div>}</div>;
}

function ProfileDetails({profile,onClose}) {
 const access=profile?.access||{};const assignments=[...Object.entries(access.systemRoles||{}).map(([system,levels])=>`${system} / ${levels?.length?levels.join(', '):'Assigned'}`),...(access.enabledSystems||[]),...(access.otherAccess||[])];
 const uniqueAssignments=[...new Set(assignments)];
 return <section className="profile-details-popover" role="dialog" aria-labelledby="profile-details-title"><header className="modal-header"><div><p className="eyebrow">WELCOME, {profile?.name?.split(' ')[0]||'USER'}</p><h2 id="profile-details-title">Your profile</h2></div><button type="button" className="icon-button" onClick={onClose} aria-label="Close profile details"><Icon name="close"/></button></header><div className="profile-details-grid">{[['Full name',profile?.name],['Employee / System ID',profile?.employeeId||profile?.systemId],['Role',profile?.role],['Designation',profile?.designation],['Department',profile?.department],['Branch',profile?.branch]].map(([label,value])=><div key={label}><small>{label}</small><strong>{value||'—'}</strong></div>)}</div><section className="profile-current-access"><h3>Current access ({uniqueAssignments.length})</h3>{uniqueAssignments.length?<ul>{uniqueAssignments.map(item=><li key={item}>{item}</li>)}</ul>:<p>No access assignments are listed.</p>}</section></section>;
}


function DeactivationSummary({details,type}) { return <section className="transfer-summary"><div className="transfer-summary-heading"><h3>{type} details</h3></div><div className="transfer-summary-grid">{[['Employee',details.name],['Employee ID',details.employeeId],['System ID',details.userId],['Department',details.department],['Branch',details.branch]].map(([label,value])=><div key={label}><small>{label}</small><strong>{value||'—'}</strong></div>)}</div>{type==='Employee ID deactivation'&&<p className="request-flow-note">Deactivate the employee identity and all associated system access.</p>}{type==='System ID deactivation'&&<p className="request-flow-note">Only the listed system IDs are requested for deactivation. Other access remains active.</p>}{type!=='Employee ID deactivation'&&<ul>{(details.systems||[]).map(system=><li key={system}>{system}</li>)}</ul>}</section>; }
function UpgradeSummary({details,requester}) {const systems=details.systems||[];return <section className="transfer-summary"><div className="transfer-summary-heading"><h3>System access and role change request</h3></div><div className="upgrade-summary-table"><table><thead><tr><th>System</th><th>Current role</th><th>Requested role</th></tr></thead><tbody>{systems.map(system=>{const current=details.currentAccess?.[system]||[];const hasCurrent=current.length>0||(details.currentEnabledSystems||[]).includes(system)||(details.currentOtherAccess||[]).includes(system);return <tr key={system}><td>{system}</td><td>{current.join(', ')||(hasCurrent?'Access enabled':'No access')}</td><td>{details.roles?.[system]||'Access request'}</td></tr>;})}</tbody></table></div><p>Requested by {requester}.</p></section>;}
const formatDhakaTimestamp = value => value ? new Intl.DateTimeFormat('en-BD',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Dhaka'}).format(new Date(value)) : 'Timestamp unavailable';
function TicketDetail({ticket,role,profile,users,onBack,onAction,focusReply=false}) {
 useEffect(()=>{
   if (!focusReply) return;
   const frame=requestAnimationFrame(()=>{
     const section=document.getElementById('ticket-query-reply');
     section?.scrollIntoView({block:'center',behavior:'instant'});
     section?.querySelector('textarea')?.focus({preventScroll:true});
   });
   return ()=>cancelAnimationFrame(frame);
 },[ticket.id,focusReply]);
 const [remark,setRemark]=useState('');
 const [query,setQuery]=useState('');
 const [targets,setTargets]=useState([]);
 const [showSummary,setShowSummary]=useState(false);
 const [formView,setFormView]=useState(null);
 const canReview=approvalRoles.includes(role)&&ticket.assignedRole===role&&ticket.state!=='Approved'&&ticket.state!=='Rejected';
 const canRespond=ticket.state==='Query'&&(ticket.queryTargetIds||[]).includes(profile?.employeeId);
 const flow=ticket.action==='System ID deactivation'?deactivationFlow(ticket.requesterRole):ticket.action==='ID reset / unlock'?['Requester','Branch manager','IT','CITO']:['Requester','Branch manager','IT','CITO','COO'];
 const normalizeStage=value=>String(value||'').toLowerCase().replace(/\s+(review|final approval)$/,'').trim();
 const approvalEventFor=step=>(ticket.approvalHistory||[]).find(event=>normalizeStage(event.stage)===normalizeStage(step)||normalizeStage(event.role)===normalizeStage(step));
 const ranks={'User':0,'HR':1,'Branch manager':1,'Department head':1,'IT':2,'CITO':3,'COO':4,'Super Admin':5};
 const currentRank=ranks[role]??0;
 const queryRecipients=users.filter(user=>user.employeeId!==profile?.employeeId&&(ranks[user.role]??0)<=currentRank);
 const currentFlowRole=ticket.assignedRole||(ticket.state==='Query'?ticket.queryReturnRole:null);
 const approvalForStep=step=>{const event=approvalEventFor(step);if(event)return `${event.status} by ${event.by} - ${formatDhakaTimestamp(event.at)}${event.remark?` - ${event.remark}`:''}`;return currentFlowRole&&normalizeStage(currentFlowRole)===normalizeStage(step)?ticket.step:'Upcoming approval step';};
 const sequence=[{title:'Request submitted',actor:ticket.name,role:'Requester',at:ticket.createdAt,message:ticket.justification},...(ticket.approvalHistory||[]).map(item=>({title:item.status,actor:item.by,role:item.role||item.stage,at:item.at,message:item.remark})),...(ticket.queryHistory||[]).flatMap(item=>[{title:'Query raised',actor:item.by,role:item.role,at:item.at,message:`To ${(item.targetNames||[]).join(', ')}: ${item.message}`},...(item.responses||[]).map(response=>({title:'Query response',actor:response.responseBy,role:users.find(user=>user.employeeId===response.employeeId)?.role||'User',at:response.responseAt,message:response.response}))]),...(ticket.remarks||[]).map(item=>({title:'Remark',actor:item.by,role:item.role,at:item.at,message:item.message}))].filter(item=>item.at).sort((a,b)=>new Date(a.at)-new Date(b.at));
 const submitQuery=()=>{if(query.trim()&&targets.length){onAction('Query',{message:query,targetIds:targets,remark});setQuery('');setRemark('');setTargets([]);}};
 const submitResponse=()=>{if(query.trim()){onAction('Responded',{message:query,remark});setQuery('');setRemark('');}};
 return <section className="detail-layout">
  <div className="panel detail-main">
   <div className="ticket-detail-toolbar"><button className="back-link" onClick={onBack}>Back to requests</button><button type="button" className="button button-subtle" onClick={()=>setShowSummary(true)}>View request summary</button><button type="button" className="button button-subtle" onClick={()=>setFormView('preview')}>Preview Form</button>{approvalRoles.includes(role)&&<button type="button" className="button" onClick={()=>setFormView('print')}>Print</button>}</div>
   <div className="detail-heading"><div><p className="eyebrow">TICKET - {ticket.id}</p><h1>{ticket.action}</h1><p>{ticket.name} - {ticket.branch} - submitted {ticket.date}</p></div><Status>{ticket.state}</Status></div>
   <div className="detail-facts"><div><small>SYSTEM</small><strong>{ticket.system}</strong></div><div><small>REQUESTED ROLE</small><strong>{ticket.role}</strong></div><div><small>CURRENT OWNER</small><strong>{ticket.step}</strong></div></div>
   {ticket.transferDetails&&<TransferSummary details={ticket.transferDetails} title={ticket.action==='Branch transfer'?'Branch Transfer':'Self Request'} ticket={ticket} flow={flow}/>}
   {ticket.newUserDetails&&<NewUserSummary people={ticket.newUserDetails.people||[]}/>}
   {ticket.batchDetails&&<BatchAccessSummary type={ticket.action} people={ticket.batchDetails.people||[]}/>}{ticket.upgradeDetails&&<UpgradeSummary details={ticket.upgradeDetails} requester={ticket.name}/>}{ticket.emailCreationDetails&&<EmailCreationSummary details={ticket.emailCreationDetails}/>}
   {ticket.resetDetails&&<ResetSummary details={ticket.resetDetails}/>}
   {ticket.deactivationDetails&&<DeactivationSummary details={ticket.deactivationDetails} type={ticket.action}/>}
   <ApprovalWorkflow ticket={ticket} flow={flow} users={users}/>
   <div className="ticket-justification"><strong>Business justification</strong><p>{ticket.justification||'Required to perform assigned business responsibilities.'}</p></div>
   <section className="ticket-interactions">
    {canReview&&<div className="remark-composer"><label className="field-label">Add remark<textarea value={remark} onChange={event=>setRemark(event.target.value)} placeholder="Add context or justification to this ticket"/></label><button type="button" onClick={()=>{if(remark.trim()){onAction('Remark',{remark});setRemark('');}}}>Save remark</button></div>}
    {canReview&&<section className="ticket-review-controls"><h3>Review actions</h3><div className="query-composer"><label className="field-label">Query lower-level users<select multiple value={targets} onChange={event=>setTargets([...event.target.selectedOptions].map(option=>option.value))}>{queryRecipients.map(user=><option key={user.employeeId} value={user.employeeId}>{user.name} - {user.role}</option>)}</select><small>You can query users at your level or below. They can reply on this ticket.</small></label><label className="field-label">Query and justification<textarea value={query} onChange={event=>setQuery(event.target.value)} placeholder="Explain what information is needed"/></label><button type="button" onClick={submitQuery} disabled={!query.trim()||!targets.length}>Send query</button></div><div className="decision-controls"><button type="button" onClick={()=>onAction('Rejected',{remark})}>Reject</button><Button onClick={()=>onAction('Approved',{remark})}>Approve and continue</Button></div></section>}
    {canRespond&&<section id="ticket-query-reply" className="query-response-composer"><h3>Reply to query</h3><p>{ticket.queryHistory?.at(-1)?.message}</p><label className="field-label">Your response<textarea value={query} onChange={event=>setQuery(event.target.value)} placeholder="Provide the requested justification or answer"/></label><Button onClick={submitResponse} disabled={!query.trim()}>Send response</Button></section>}
   </section>
  </div>
  <aside className="panel audit-panel"><h3>Approval sequence and audit trail</h3><p>Approver actions, queries, responses, remarks, and Dhaka timestamps.</p>{sequence.map((event,index)=><div className="audit-event approval-sequence-event" key={`${event.at}-${index}`}><i/><div><strong>{event.title}</strong><small>{event.actor} - {event.role} - {formatDhakaTimestamp(event.at)}</small>{event.message&&<small>{event.message}</small>}</div></div>)}</aside>
  {formView&&<RequestModal ticket={ticket} initialType={ticket.action} profile={users.find(user=>user.employeeId===ticket.requesterId)||{}} users={users} onClose={()=>setFormView(null)} printOnOpen={formView==='print'}/>}
  {showSummary&&<RequestSummaryModal ticket={ticket} flow={flow} sequence={sequence} currentFlowRole={currentFlowRole} onClose={()=>setShowSummary(false)}/>}
 </section>;
}

function SnapshotFields({value}) {
 if(Array.isArray(value))return value.length?<div className="request-snapshot-list">{value.map((entry,index)=><div className="request-snapshot-item" key={index}>{entry&&typeof entry==='object'?<SnapshotFields value={entry}/>:String(entry)}</div>)}</div>:<span className="snapshot-empty">None provided</span>;
 if(!value||typeof value!=='object')return <strong>{String(value??'—')}</strong>;
 const entries=Object.entries(value).filter(([key,item])=>item!==undefined&&item!==null&&item!==''&&!['signature','profileEmail','requesterName'].includes(key));
 if(!entries.length)return <span className="snapshot-empty">No additional details</span>;
 return <div className="request-snapshot-grid">{entries.map(([key,item])=><div className="request-snapshot-field" key={key}><small>{key.replace(/([A-Z])/g,' $1').replace(/^./,letter=>letter.toUpperCase())}</small>{Array.isArray(item)||typeof item==='object'?<SnapshotFields value={item}/>:<strong>{String(item)}</strong>}</div>)}</div>;
}

function requestedAccessRows(ticket) {
 const rows=[];
 const add=(system,requestedRole,employee='Request subject',requestType=ticket.action)=>{if(system)rows.push({system,requestedRole:requestedRole||'No role specified',employee,requestType});};
 const transfer=ticket.transferDetails||{};
 for(const [key,label] of [['newAccess','New system access'],['newOtherAccess','New other access'],['newTestSystems','New test system access'],['additionalTestSystems','Additional test system access'],['currentAccess','Current system access'],['currentOtherAccess','Current other access'],['currentTestSystems','Current test system access']]){
  const access=transfer[key]||{};const flags=transfer[`${key}Systems`]||{};
  for(const [system,selectedRole] of Object.entries(access))if(flags[system]||selectedRole?.length)add(system,Array.isArray(selectedRole)?selectedRole.join(', '):selectedRole,label);
 }
 for(const person of transfer.people||[])for(const requested of person.requestedSystems||[])add(requested.system,requested.role,person.fullName||person.name||person.employeeId||'Employee','Branch transfer');
 for(const person of ticket.batchDetails?.people||[])for(const requested of person.systems||[])add(requested.system,requested.role,person.name||person.employeeId||'Employee');
 for(const person of ticket.newUserDetails?.people||[]){if(person.adId)add('Active Directory ID',person.adRole||'New account',person.name||person.employeeId||'New employee','New ID creation');if(person.email)add('Email account',person.preferredEmail||'New email',person.name||person.employeeId||'New employee','New ID creation');if(person.msOffice)add('MS Office','Software access',person.name||person.employeeId||'New employee','New ID creation');if(person.otherSoftware)add(person.otherSoftware,'Software access',person.name||person.employeeId||'New employee','New ID creation');}
 for(const [system,level] of Object.entries(ticket.upgradeDetails?.roles||{}))add(system,level,ticket.name,'ID upgrade');
 for(const group of ticket.mailingGroupDetails?.groupAddresses||[])add(group,`Group ${ticket.mailingGroupDetails.action}`,ticket.name,'Mailing group change');
 if(ticket.emailCreationDetails)add('Email',ticket.emailCreationDetails.email||'Mailbox creation',ticket.emailCreationDetails.name||ticket.name,'Email creation');
 if(ticket.externalDeviceDetails)add('External device email access',`${ticket.externalDeviceDetails.deviceModel} / ${ticket.externalDeviceDetails.deviceNumber} / ${ticket.externalDeviceDetails.serialNumber}`,ticket.externalDeviceDetails.name||ticket.name,'External device email access');
 for(const system of ticket.resetDetails?.systems||[])add(system,'Reset / unlock',ticket.resetDetails.name||ticket.resetDetails.employeeId||'Employee','ID reset / unlock');
 for(const system of ticket.deactivationDetails?.systems||[])add(system,'Deactivate ID',ticket.deactivationDetails.name||ticket.deactivationDetails.employeeId||'Employee',ticket.action);
 if(!rows.length)add(ticket.system,ticket.role,ticket.name,ticket.action);
 return rows;
}

function RequestSummaryModal({ticket,flow,sequence,currentFlowRole,onClose}) {
 const formSections=[['Request details',{requestType:ticket.action,requester:ticket.name,employeeId:ticket.requesterId,branch:ticket.branch,system:ticket.system,requestedRole:ticket.role}],['New ID request',ticket.newUserDetails],['Branch transfer / system access form',ticket.transferDetails],['Batch access request',ticket.batchDetails],['ID upgrade form',ticket.upgradeDetails],['Email creation form',ticket.emailCreationDetails],['External device access form',ticket.externalDeviceDetails],['ID reset / unlock form',ticket.resetDetails],[ticket.action+' form',ticket.deactivationDetails],['Email auto-forward form',ticket.autoForwardDetails],['Mailing group form',ticket.mailingGroupDetails]].filter(([,value])=>value&&(!Array.isArray(value)||value.length));
 const accessRows=requestedAccessRows(ticket);
 return <div className="request-summary-scrim" onMouseDown={event=>event.target===event.currentTarget&&onClose()}><section className="request-summary-modal" role="dialog" aria-modal="true" aria-labelledby="request-summary-title"><header className="request-summary-header"><div><p className="eyebrow">REQUEST REVIEW</p><h2 id="request-summary-title">{ticket.action} - {ticket.id}</h2><p>{ticket.name} · {ticket.branch} · {formatDhakaTimestamp(ticket.createdAt)}</p></div><button type="button" className="icon-button" onClick={onClose} aria-label="Close request summary">×</button></header><div className="request-summary-content"><section className="request-summary-executive"><h3>Executive summary</h3><div className="request-summary-meta">{[['Status',ticket.state],['Current owner',ticket.step],['Requester',ticket.name],['Employee ID',ticket.requesterId],['Branch',ticket.branch],['System',ticket.system],['Requested role',ticket.role]].map(([label,value])=><div key={label}><small>{label}</small><strong>{value||'—'}</strong></div>)}</div><section className="request-summary-access"><h4>Systems and roles requested</h4><div className="request-summary-access-table"><table><thead><tr><th>System</th><th>Requested role / action</th><th>For</th><th>Request type</th></tr></thead><tbody>{accessRows.map((row,index)=><tr key={`${row.system}-${row.employee}-${index}`}><td>{row.system}</td><td>{row.requestedRole}</td><td>{row.employee}</td><td>{row.requestType}</td></tr>)}</tbody></table></div></section><div className="request-summary-justification"><strong>Business justification</strong><p>{ticket.justification||'No business justification was provided.'}</p></div></section><section className="request-summary-form"><h3>Submitted request form</h3>{formSections.map(([title,value])=><article className="request-snapshot-section" key={title}><h4>{title}</h4><SnapshotFields value={value}/></article>)}</section><section className="request-summary-flow"><h3>Approval flow</h3><div className="request-summary-steps">{flow.map((step,index)=>{const event=(ticket.approvalHistory||[]).find(item=>String(item.stage||item.role||'').toLowerCase().replace(/\s+(review|final approval)$/,'')===step.toLowerCase());const done=step==='Requester'||Boolean(event);const current=currentFlowRole&&String(currentFlowRole).toLowerCase().replace(/\s+(review|final approval)$/,'')===step.toLowerCase();return <div className={`request-summary-step ${done?'done':''} ${current?'current':''}`} key={step}><span>{done?'✓':index+1}</span><div><strong>{step}</strong><small>{event?`${event.status} by ${event.by} · ${formatDhakaTimestamp(event.at)}`:current?ticket.step:'Upcoming'}</small>{event?.remark&&<p>{event.remark}</p>}</div></div>;})}</div><h4>Queries, responses, and remarks</h4>{sequence.map((event,index)=><div className="request-summary-event" key={`${event.at}-${index}`}><strong>{event.title}</strong><small>{event.actor} · {event.role} · {formatDhakaTimestamp(event.at)}</small>{event.message&&<p>{event.message}</p>}</div>)}</section></div></section></div>;
}
const departmentMailingGroups=new Set(['IT','Clearing','Treasury','Corporate banking','Trade','Mancom','SWB']);
const defaultMailingGroups=['#IT/CBC/Dhaka/Bangladesh','#Dhanmondi Branch/CBC/Dhaka/Bangladesh','#Panthapath Branch/CBC/Dhaka/Bangladesh',...['Gulshan','Corporate','Old Dhaka','Uttara','Mirpur','Shantinagar','Motijheel','CEPZ','Agrabad','Sylhet','Clearing','Treasury','Corporate banking','Trade','Mancom','SWB'].map(name=>`#${name}/CBC/Dhaka/Bangladesh`)].map(address=>({address,members:[],category:departmentMailingGroups.has(address.split('/')[0].replace(/^#/,'').trim())?'Department':'Branch'}));
function mergeDefaultMailingGroups(groups=[]){const merged=[...groups];for(const group of defaultMailingGroups){const existing=merged.find(item=>item.address.toLowerCase()===group.address.toLowerCase());if(!existing)merged.push(group);else if(!existing.category)existing.category=group.category;}return merged;}
