function SystemCatalog({onRequest}) {return <section className="panel directory-panel"><SectionTitle eyebrow="ACCESS CATALOG" title="Systems & services"><Button icon="plus" onClick={onRequest}>Request access</Button></SectionTitle><p className="directory-intro">Browse all services. Select Request to open a prefilled access form.</p><div className="catalog-grid">{systems.map((s,i)=><article className="catalog-card" key={s}><span className={`service-mark sm-${i%5}`}>{s.slice(0,1)}</span><div><strong>{s}</strong><small>{i<9?'Core banking':'Business & identity'}  |  Access request enabled</small></div><button onClick={onRequest}>Request</button></article>)}</div></section>;}
function WorkflowStudio({notify}) {return <section className="panel directory-panel"><SectionTitle eyebrow="ADMINISTRATION" title="Workflow studio"><Button icon="plus" onClick={()=>notify('New workflow draft created.')}>Create workflow</Button></SectionTitle><p className="directory-intro">Configure reusable approval flows by request type and system. Changes are shown as drafts in this mockup.</p>{['Standard system access','Reset / enable ID','Query ID','WBO access','CITRIX_R access','New joiner (on behalf)'].map((x,i)=><div className="workflow-row" key={x}><div><strong>{x}</strong><small>{i===0?'System scoped  |  31 services':'Reusable workflow  |  '+(i+4)+' approval steps'}</small></div><div className="flow-chips">{['Requester',i===5?'HR':'Manager','IT','CITO',...(i===2?['Email']:['COO','IT'])].map(n=><span key={n}>{n}</span>)}</div><Button variant="subtle" onClick={()=>notify(`${x} opened for editing.`)}>Edit flow</Button></div>)}</section>;}
